function verify_dalga25_stage4(output_dir, only_case)
  % Acceptance recipe for the orchestrator's fresh Qt Octave copy ONLY.
  % No graphics or MATLAB measurements were run while authoring this file.
  % Each case is independent; only_case avoids the 12-figure execute export cap.
  % With output_dir, inspect actual serializer JSON and assert immutability.
  % Octave 11.3 patch FaceColor enum has no texturemap value. Texture
  % rejection belongs in protocol/unit tests, not an unconstructible figure.
  % Contour zlevel/zlevelmode are Octave extensions, not MATLAB assertions.
  if nargin<1,output_dir='';end
  if nargin<2,only_case='';end
  cases={...
    'contour levels', '', 'contour(x,y,z,[-.5 0 .5]);colormap([1 0 0;0 1 0;0 0 1]);caxis([-1 1]);';...
    'contour closed paths', '', 'contour(x,y,x.^2+y.^2,[1 1]);';...
    'contour3 styles', '', '[~,h]=contour3(x,y,z,[-.5 0 .5]);set(h,"linestyle","--","linewidth",2.5);';...
    'contour manual zlevel', '', '[~,h]=contour(x,y,z,[0 0]);set(h,"zlevelmode","manual","zlevel",2,"linecolor",[.2 .7 .3]);view(3);';...
    'surfc resolved contours', '', 'surfc(x,y,z,"facecolor",[.3 .6 .8],"edgecolor","none");';...
    'meshc resolved contours', '', 'meshc(x,y,z);';...
    'contourf bounded patches', '', 'contourf([0 1;0 1],[.25 .75]);';...
    'clabel 3D depth fallback', 'contour_labels', '[c,h]=contour3(x,y,z,[-.5 0 .5]);clabel(c,h);';...
    'clabel matrix 2D', '', 'c=contour(x,y,x.^2+y.^2,[1 2 3]);clabel(c);';...
    'patch RGB convex', '', 'patch("vertices",v,"faces",[1 2 3 4],"facecolor",[.2 .6 .8],"edgecolor","none");view(2);axis([0 1 0 1 0 2]);axis off;';...
    'fill3 XYZ concave', '', 'fill3([0 2 2 1 0],[0 0 2 1 2],ones(1,5),[.2 .6 .8],"edgecolor",[.1 .1 .1],"linestyle",":","linewidth",2);view(3);';...
    'patch NaN face padding', '', 'patch("vertices",[v;2 0 1;3 0 1;2.5 1 1],"faces",[1 2 3 4;5 6 7 NaN],"facecolor",[.2 .6 .8],"edgecolor","none");view(3);';...
    'patch indexed face flat', '', 'patch("vertices",[v;v+[2 0 0]],"faces",[1 2 3 4;5 6 7 8],"facevertexcdata",[1;2],"facecolor","flat","edgecolor","none","cdatamapping","direct");colormap([1 0 0;0 0 1]);view(3);';...
    'patch RGB face flat', '', 'patch("vertices",[v;v+[2 0 0]],"faces",[1 2 3 4;5 6 7 8],"facevertexcdata",[1 0 0;0 0 1],"facecolor","flat","edgecolor","none");view(3);';...
    'patch edge only', '', 'patch("vertices",v,"faces",[1 2 3 4],"facecolor","none","edgecolor",[.2 .6 .8],"linestyle","--");view(3);';...
    'patch polygon face interp PNG', 'interpolated_color', 'patch("vertices",v,"faces",[1 2 3 4],"facevertexcdata",[0;1;2;3],"facecolor","interp","edgecolor","interp");view(3);';...
    'patch scalar alpha', '', 'patch("vertices",v,"faces",[1 2 3 4],"facecolor",[.2 .6 .8],"facealpha",.5);view(3);';...
    'patch lighting fallback', 'lighting', 'patch("vertices",v,"faces",[1 2 3 4],"facecolor",[.2 .6 .8],"facelighting","flat");light;view(3);';...
    'patch nonplanar fallback', 'unsupported_patch', 'v(4,3)=1.2;patch("vertices",v,"faces",[1 2 3 4],"facecolor",[.2 .6 .8]);view(3);';...
    'patch bowtie fallback', 'unsupported_patch', 'patch("vertices",v,"faces",[1 3 2 4],"facecolor",[.2 .6 .8]);view(3);';...
    'patch degenerate fallback', 'unsupported_patch', 'patch("vertices",[0 0 1;1 0 1;2 0 1],"faces",[1 2 3],"facecolor",[.2 .6 .8]);view(3);';...
    'patch 64 vertices', '', 'q=(0:63)''*2*pi/64;patch("vertices",[cos(q),sin(q),ones(64,1)],"faces",1:64,"facecolor",[.2 .6 .8],"edgecolor","none");view(3);';...
    'patch 65 vertices fallback', 'budget_exceeded', 'q=(0:64)''*2*pi/65;patch("vertices",[cos(q),sin(q),ones(65,1)],"faces",1:65,"facecolor",[.2 .6 .8]);view(3);';...
    'patch vertex budget fallback', 'budget_exceeded', 'patch("vertices",[v;zeros(39997,2),ones(39997,1)],"faces",[1 2 3 4],"facecolor",[.2 .6 .8]);view(3);';...
    'patch triangle budget fallback', 'budget_exceeded', 'patch("vertices",v,"faces",repmat([1 2 3],80001,1),"facecolor",[.2 .6 .8]);view(3);';...
    'patch marker fallback', 'unsupported_patch', 'patch("vertices",v,"faces",[1 2 3 4],"facecolor",[.2 .6 .8],"marker","o");view(3);';...
    'patch per vertex flat fallback', 'patch_colors', 'patch("vertices",v,"faces",[1 2 3 4],"facevertexcdata",[1;2;3;4],"facecolor","flat");view(3);';...
    'patch ambiguous flat fallback', 'patch_colors', 'patch("vertices",[0 0 1;1 0 1;0 1 1],"faces",[1 2 3;2 3 1;3 1 2],"facevertexcdata",[1;2;3],"facecolor","flat");view(3);';...
    'clabel group 2D rotated', '', '[c,h]=contour(x,y,z,[-.5 0 .5]);clabel(c,h,"rotation",35);';...
    'patch data alpha fallback', 'transparency', 'patch("vertices",v,"faces",[1 2 3 4],"facecolor",[.2 .6 .8],"facealpha","interp","facevertexalphadata",[0;.25;.5;1],"alphadatamapping","none");view(3);'...
  };
  [x,y]=meshgrid(linspace(-2,2,9));z=x.^2-y.^2;
  for i=1:rows(cases)
    if ~isempty(only_case)&&~strcmp(only_case,cases{i,1}),continue;end
    v=[0 0 1;1 0 1;1 1 1;0 1 1];
    f=figure('name',['D25 ' cases{i,1}],'position',[0 0 400 400]);
    eval(cases{i,3});
    if isempty(output_dir),continue;end
    handles=sort(findall(f));before=cell(size(handles));
    for j=1:numel(handles),before{j}=get(handles(j));end
    current=get(0,'currentfigure');
    data=__mf_figure_data__(f,struct('job',repmat('f',1,32),'figure',i));
    assert(isequal(handles,sort(findall(f))));assert(isequaln(current,get(0,'currentfigure')));
    for j=1:numel(handles),assert(isequaln(before{j},get(handles(j))));end
    if isempty(cases{i,2})
      assert(data.supported,['Expected interactive: ' cases{i,1}]);
    else
      assert(~data.supported&&strcmp(data.reason_code,cases{i,2}),['Expected ' cases{i,2} ': ' cases{i,1}]);
    end
    if strcmp(cases{i,1},'patch scalar alpha')
      assert(isequal(data.axes{1}.series{1}.face_alpha,struct('mode','constant','association','constant','value',.5)));
    elseif strcmp(cases{i,1},'patch data alpha fallback')
      assert(strcmp(data.reason_args.detail,'unmeasured_data_mapping'));
    end
    if ~exist(output_dir,'dir'),mkdir(output_dir);end
    file=fopen(fullfile(output_dir,sprintf('stage4_%02d.json',i)),'w');assert(file>=0);
    fputs(file,jsonencode(data));fclose(file);
  end
end
